package com.mahesh.empleave.user;
import com.fasterxml.jackson.annotation.JsonIgnore;import com.mahesh.empleave.department.Department;import jakarta.persistence.*;import lombok.*;
@Entity @Table(name="users") @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class AppUser { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true,nullable=false) private String email; @JsonIgnore @Column(nullable=false) private String password; @Enumerated(EnumType.STRING) @Column(nullable=false) private Role role; @Column(nullable=false) private String fullName; @ManyToOne(fetch=FetchType.LAZY) private Department department; @ManyToOne(fetch=FetchType.LAZY) private AppUser manager; public AppUser(String email,String password,Role role,String fullName){this.email=email;this.password=password;this.role=role;this.fullName=fullName;} public void update(String name,Department dept,AppUser supervisor,Role assignedRole){fullName=name;department=dept;manager=supervisor;role=assignedRole;} public void updateOwnProfile(String name){fullName=name;} }
